        if all(not isinstance(c, list) for c in node):
            return pad + "(" + " ".join(_leaf(c) for c in node) + ")"
        parts = [pad + "(" + _head(node)]
        for c in node[1:]:
            parts.append(dumps(c, indent + 1))
        parts.append(pad + ")")
        return "\n".join(parts)
    return pad + _leaf(node)

